279:   public void processInstanceHasActiveUserTasks(
280:       final CamundaClient client,
281:       final Long processInstanceKey,
282:       final Map<String, Long> userTaskCounts) {
283:     flowNodeInstanceExistAndMatches(
284:         client,
285:         f ->
286:             f.processInstanceKey(processInstanceKey)
287:                 .state(ElementInstanceState.ACTIVE)
288:                 .type(ElementInstanceType.USER_TASK),
289:         f -> {
290:           final var elementIdCounts =
291:               f.stream()
292:                   .collect(
293:                       Collectors.groupingBy(ElementInstance::getElementId, Collectors.counting()));
294:           assertThat(elementIdCounts).containsAllEntriesOf(userTaskCounts);
295:         });
296:   }
297: 
298:   public void flowNodeInstanceExistAndMatches(
299:       final CamundaClient client,
300:       final Consumer<ElementInstanceFilter> filter,
301:       final Consumer<List<ElementInstance>> asserter) {
302:     await()
303:         .atMost(TIMEOUT_DATA_AVAILABILITY)
304:         .untilAsserted(
305:             () -> {
306:               final var result =
307:                   client.newElementInstanceSearchRequest().filter(filter).send().join().items();
308:               asserter.accept(result);
309:             });
310:   }
311: }
