395:     }
396: 
397:     if (connectTimeout == null) {
398:       connectTimeout = DEFAULT_CONNECT_TIMEOUT;
399:     }
400: 
401:     if (readTimeout == null) {
402:       readTimeout = DEFAULT_READ_TIMEOUT;
403:     }
404:   }
