32: import org.slf4j.LoggerFactory;
33: 
34: /**
35:  * This class provides methods to fetch entities for batch operations. It uses the search client
36:  * proxy to access the secondary database.
37:  */
38: public class BatchOperationItemProvider {
39: 
40:   private static final Logger LOG = LoggerFactory.getLogger(BatchOperationItemProvider.class);
41: 
42:   private final SearchClientsProxy searchClientsProxy;
43:   private final BatchOperationMetrics metrics;
44: 
45:   /**
46:    * The size of a page when fetching entities. This is the maximum number of items that can be
47:    * fetched in a single query and is limited by ElasticSearch.
48:    */
49:   private final int queryPageSize;
50: 
51:   /**
52:    * The maximum number of keys that can be passed in a single IN clause in a query. This is limited
53:    * to 1000 because the Oracle DB supports a maximum of 1000 elements in an IN clause.
54:    */
55:   private final int inClauseSize;
56: 
57:   public BatchOperationItemProvider(
58:       final SearchClientsProxy searchClientsProxy,
59:       final EngineConfiguration engineConfiguration,
60:       final BatchOperationMetrics metrics) {
61:     this.searchClientsProxy = searchClientsProxy;
62:     this.metrics = metrics;
63:     queryPageSize = engineConfiguration.getBatchOperationQueryPageSize();
64:     inClauseSize = engineConfiguration.getBatchOperationQueryInClauseSize();
65:   }
66: 
67:   /**
68:    * Fetches the process instance items for the given partitionId based on the provided filter. The
69:    * items are fetched sequentially in pages. Depending on the overall size of the result, this can
70:    * cause multiple queries to the secondary database.
71:    *
72:    * @param filter the filter to use
73:    * @param authentication the authentication to use
74:    * @param shouldAbort if the process should be aborted
75:    * @return a set of all found process instance items
76:    */
77:   public Set<Item> fetchProcessInstanceItems(
78:       final int partitionId,
79:       final ProcessInstanceFilter filter,
80:       final Authentication authentication,
81:       final Supplier<Boolean> shouldAbort) {
82:     final var processInstanceFilter = filter.toBuilder().partitionId(partitionId).build();
83: 
84:     LOG.debug(
85:         "Fetching process instance items for partition {} with filter: {}",
86:         partitionId,
87:         processInstanceFilter);
88: 
89:     return fetchEntityItems(
90:         new ProcessInstancePageFetcher(), processInstanceFilter, authentication, shouldAbort);
91:   }
92: 
93:   /**
94:    * Fetches the incident items based on the provided incident filter. The items are fetched
95:    * sequentially in pages. Depending on the overall size of the result this can cause multiple
96:    * queries to the secondary database.
97:    *
98:    * @param filter the filter to use
99:    * @param authentication the authentication to use
100:    * @param shouldAbort if the process should be aborted
101:    * @return a set of all found process instance items
102:    */
103:   public Set<Item> fetchIncidentItems(
104:       final IncidentFilter filter,
105:       final Authentication authentication,
106:       final Supplier<Boolean> shouldAbort) {
107: 
108:     LOG.debug("Fetching incident items with filter: {}", filter);
109:     return fetchEntityItems(new IncidentPageFetcher(), filter, authentication, shouldAbort);
110:   }
111: 
112:   /**
113:    * Fetches the incident items based on the provided process instance filter for the given
114:    * partitonId. This will return <b>ALL</b> incidents of the matching processInstances. The items
115:    * are fetched sequentially in pages. Depending on the overall size of the result, this can cause
116:    * multiple queries to the secondary database.
117:    *
118:    * @param filter the filter to use
119:    * @param authentication the authentication to use
120:    * @param shouldAbort if the process should be aborted
121:    * @return a set of all found incident items
122:    */
123:   public Set<Item> fetchIncidentItems(
124:       final int partitionId,
125:       final ProcessInstanceFilter filter,
126:       final Authentication authentication,
127:       final Supplier<Boolean> shouldAbort) {
128:     // first fetch all matching processInstances
129:     final var processInstanceKeys =
130:         fetchProcessInstanceItems(partitionId, filter, authentication, shouldAbort).stream()
131:             .map(Item::processInstanceKey)
132:             .toList();
133: 
134:     // then fetch all incidents of the matching processInstances
135:     return getIncidentItemsOfProcessInstanceKeys(
136:         new ArrayList<>(processInstanceKeys), authentication, shouldAbort);
137:   }
138: 
139:   private <F extends FilterBase> Set<Item> fetchEntityItems(
140:       final ItemPageFetcher<F> itemPageFetcher,
141:       final F filter,
142:       final Authentication authentication,
143:       final Supplier<Boolean> shouldAbort) {
144:     final var items = new LinkedHashSet<Item>();
145: 
146:     Object[] searchValues = null;
147:     while (true) {
148:       // Check if the batch operation is still present, could be canceled in the meantime
149:       if (shouldAbort.get()) {
150:         LOG.warn("Batch operation is no longer active, stopping query.");
151:         return Set.of();
152:       }
153: 
154:       metrics.recordQueryAgainstSecondaryDatabase();
155: 
156:       final var result = itemPageFetcher.fetchItems(filter, searchValues, authentication);
157:       items.addAll(result.items);
158:       searchValues = result.lastSortValues();
159: 
160:       // the result.total count can be incorrect when using elasticsearch and could be capped at
161:       // 10_000. If the result.total is smaller than the queryPageSize, we can assume that we have
162:       // fetched all items. Otherwise, we fetch again until we fetch an empty page
163:       if (result.items.isEmpty() || result.total < queryPageSize) {
164:         break;
165:       }
166:     }
167: 
168:     return items;
169:   }
170: 
171:   private Set<Item> getIncidentItemsOfProcessInstanceKeys(
172:       final List<Long> processInstanceKeys,
173:       final Authentication authentication,
174:       final Supplier<Boolean> shouldAbort) {
175:     final Set<Item> incidents = new LinkedHashSet<>();
176: 
177:     final List<List<Long>> processInstanceKeysBatches =
178:         Lists.partition(processInstanceKeys, inClauseSize);
179: 
180:     for (final List<Long> processInstanceKeysBatch : processInstanceKeysBatches) {
181:       if (shouldAbort.get()) {
182:         return Set.of();
183:       }
184:       final var filter =
185:           new IncidentFilter.Builder()
186:               .processInstanceKeyOperations(
187:                   FilterUtil.mapDefaultToOperation(processInstanceKeysBatch))
188:               .build();
189:       incidents.addAll(fetchIncidentItems(filter, authentication, shouldAbort));
190:     }
191: 
192:     return incidents;
193:   }
194: 
195:   public record Item(final long itemKey, final long processInstanceKey) {}
196: 
197:   /**
198:    * Internal abstraction to hold the result of a page of entity items.
199:    *
200:    * @param items the fetched items
201:    * @param lastSortValues the last sortValues for pagination
202:    * @param total the total amount of found items
203:    */
204:   private record ItemPage(final List<Item> items, final Object[] lastSortValues, final long total) {}
205: 
206:   /**
207:    * Internal abstraction interface to get a single page of entity items of a specific type. This is
208:    * needed because the actual query to the secondary database is different for specific entity
209:    * types.
210:    *
211:    * @param <F> the filter type
212:    */
213:   private interface ItemPageFetcher<F extends FilterBase> {
214: 
215:     /**
216:      * Fetches a page of entity items based on the provided filter and search values.
217:      *
218:      * @param filter the filter to apply
219:      * @param searchAfter the current sortValues
220:      * @return the fetched items and pagination information
221:      */
222:     ItemPage fetchItems(F filter, Object[] searchAfter, Authentication authentication);
223: 
224:     /**
225:      * Creates a security context for the given authentication and authorization.
226:      *
227:      * @param authentication the authentication of the user which started the batch operation
228:      * @param authorization the same authorization is needed, that is normally used in
229:      *     ProcessInstanceServices / IncidentServices
230:      * @return the security context
231:      */
232:     default SecurityContext createSecurityContext(
233:         final Authentication authentication, final Authorization authorization) {
234:       return SecurityContext.of(
235:           b -> b.withAuthentication(authentication).withAuthorization(authorization));
236:     }
237:   }
238: 
239:   private final class ProcessInstancePageFetcher implements ItemPageFetcher<ProcessInstanceFilter> {
240:     @Override
241:     public ItemPage fetchItems(
242:         final ProcessInstanceFilter filter,
243:         final Object[] searchAfter,
244:         final Authentication authentication) {
245:       final var securityContext =
246:           createSecurityContext(
247:               authentication, Authorization.of(a -> a.processDefinition().readProcessInstance()));
248:       final var page =
249:           SearchQueryPageBuilders.page().size(queryPageSize).searchAfter(searchAfter).build();
250:       final var query =
251:           SearchQueryBuilders.processInstanceSearchQuery()
252:               .filter(filter)
253:               .page(page)
254:               .resultConfig(c -> c.onlyKey(true))
255:               .build();
256: 
257:       final SearchQueryResult<ProcessInstanceEntity> result =
258:           searchClientsProxy.withSecurityContext(securityContext).searchProcessInstances(query);
259: 
260:       return new ItemPage(
261:           result.items().stream()
262:               .map(pi -> new Item(pi.processInstanceKey(), pi.processInstanceKey()))
263:               .collect(Collectors.toList()),
264:           result.lastSortValues(),
265:           result.total());
266:     }
267:   }
268: 
269:   private final class IncidentPageFetcher implements ItemPageFetcher<IncidentFilter> {
270:     @Override
271:     public ItemPage fetchItems(
272:         final IncidentFilter filter,
273:         final Object[] searchAfter,
274:         final Authentication authentication) {
275:       final var securityContext =
276:           createSecurityContext(
277:               authentication, Authorization.of(a -> a.processDefinition().readProcessInstance()));
278:       final var page =
279:           SearchQueryPageBuilders.page().size(queryPageSize).searchAfter(searchAfter).build();
280:       final var query = SearchQueryBuilders.incidentSearchQuery().filter(filter).page(page).build();
281: 
282:       final var result =
283:           searchClientsProxy.withSecurityContext(securityContext).searchIncidents(query);
284: 
285:       return new ItemPage(
286:           result.items().stream()
287:               .map(pi -> new Item(pi.incidentKey(), pi.processInstanceKey()))
288:               .collect(Collectors.toList()),
289:           result.lastSortValues(),
290:           result.total());
291:     }
292:   }
293: }
